// Kiro's balance reflex: when the pelvis is shoved sideways, command a sideways step toward the push.
// It tracks a slow baseline of the body-frame lateral velocity (m/s); the deviation from that baseline
// is the push. The sideways command is capped at 0.6 m/s.
import type { ReflexState } from './reflex.js';

const ALPHA = 0.02;      // baseline low-pass factor per Control_Step (20 ms)
const DEADBAND = 0.1;    // m/s of lateral deviation ignored
const GAIN = 0.8;        // (m/s command) per (m/s deviation)
const VY_CAP = 0.6;      // m/s

export class KiroReflex {
  private baseline = 0;
  private primed = false;

  reset(): void { this.baseline = 0; this.primed = false; }

  command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const q = s.qpos, w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const vx = s.qvel[0] as number, vy = s.qvel[1] as number;
    // Body-frame lateral velocity: the y component of R(q)^T v, with the world-frame z velocity ignored.
    const r01 = 2 * (x * y + w * z), r11 = 1 - 2 * (x * x + z * z);
    const vLat = r01 * vx + r11 * vy;
    if (!this.primed) { this.baseline = vLat; this.primed = true; }
    const dev = vLat - this.baseline;
    this.baseline += ALPHA * dev;
    let cmd = base[1] as number;
    if (Math.abs(dev) > DEADBAND) {
      const d = dev - Math.sign(dev) * DEADBAND;
      cmd += Math.max(-VY_CAP, Math.min(VY_CAP, GAIN * d));
      cmd = Math.max(-VY_CAP, Math.min(VY_CAP, cmd));
    }
    out[0] = base[0] as number;
    out[1] = cmd;
    out[2] = base[2] as number;
  }
}

